mapper.insert:
INSERT INTO tb_nlcf_fairytale_chunk (
	chunk_id
	, fairytale_id
	, chunk_no
	, title
	, chunk_text
) VALUES (
	#{chunkId}
	, #{fairytaleId}
	, #{chunkNo}
	, #{title}
	, #{chunkText}
)

	INSERT INTO tb_nlcf_fairytale_embedding (
        embedding_id
        , chunk_id
        , embedding_model
        , title_vector
        , embedding_vector
    ) VALUES (
        #{embeddingId}
        , #{chunkId}
        , #{embeddingModel}
        , CAST(#{titleVector} AS vector)
        , CAST(#{embeddingVector} AS vector)
    )
